pub struct WorkspaceCargoResolver {
    root_path: PathBuf,
    absolute_path: PathBuf,
    document: toml_edit::DocumentMut,
}

impl WorkspaceCargoResolver {
    pub fn load(root_manifest_path: &Path) -> Result<Self, ManifestError> {
        crate::record_resolver_load_call();
        let rel_path = if root_manifest_path.is_absolute() {
            root_manifest_path
                .file_name()
                .map(PathBuf::from)
                .unwrap_or_else(|| PathBuf::from("Cargo.toml"))
        } else {
            workspace_relative(root_manifest_path).map_err(|e| ManifestError::Read {
                path: root_manifest_path.to_path_buf(),
                message: e.to_string(),
            })?
        };
        let content = fs::read_to_string(root_manifest_path).map_err(|e| ManifestError::Read {
            path: rel_path.clone(),
            message: e.to_string(),
        })?;

        let doc: toml_edit::DocumentMut = content
            .parse()
            .map_err(|e: toml_edit::TomlError| ManifestError::Parse {
                path: rel_path.clone(),
                format: ManifestFormat::CargoToml,
                message: e.to_string(),
            })?;

        Ok(WorkspaceCargoResolver {
            root_path: rel_path,
            absolute_path: root_manifest_path.to_path_buf(),
            document: doc,
        })
    }

    pub fn inheritance(&self) -> Result<WorkspaceInheritance, ManifestError> {
        let version = workspace_package_version(&self.document, &self.root_path)
            .ok()
            .flatten();

        let mut dependencies = BTreeMap::new();
        if let Some(table) = self
            .document
            .get("workspace")
            .and_then(|w| w.get("dependencies"))
            .and_then(|d| d.as_table_like())
        {
            for (name, item) in table.iter() {
                let mut kind = DepKind::Runtime;
                let spec = parse_cargo_dep_item(item, &mut kind);
                dependencies.insert(
                    name.to_string(),
                    DependencyEntry {
                        name: name.to_string(),
                        package_name: cargo_dependency_package_name(name, item).to_string(),
                        kind,
                        spec,
                        inherited: false,
                    },
                );
            }
        }

        Ok(WorkspaceInheritance {
            root_manifest: self.root_path.clone(),
            version,
            dependencies,
        })
    }

    /// Returns the `[workspace.package] version` currently on disk, or `None`
    /// when no such field exists (e.g. the workspace does not declare a shared
    /// version). Used by `apply_version_plan`'s idempotency guard.
    pub fn workspace_version(&self) -> Result<Option<Version>, ManifestError> {
        workspace_package_version(&self.document, &self.root_path)
    }

    /// Pure in-memory mutation of `[workspace.package] version` -- no disk
    /// I/O. Mirrors `CargoToml`/`PackageJson`/`PyprojectToml`'s
    /// `write_version`, which likewise never touches disk; callers must
    /// call [`Self::persist`] explicitly afterward. `_permit` is accepted
    /// (unused) purely for call-site symmetry with `persist`, which does
    /// require one.
    pub fn write_version(&mut self, v: &Version, _permit: &ApplyPermit) -> Result<(), ManifestError> {
        let ws = self
            .document
            .get_mut("workspace")
            .and_then(|w| w.as_table_like_mut())
            .ok_or_else(|| ManifestError::MissingField {
                path: self.root_path.clone(),
                field: "workspace",
            })?;

        let pkg = ws
            .entry("package")
            .or_insert(toml_edit::Item::Table(toml_edit::Table::new()))
            .as_table_mut()
            .ok_or_else(|| ManifestError::MissingField {
                path: self.root_path.clone(),
                field: "workspace.package",
            })?;

        crate::common::set_scalar_preserving_decor(pkg, "version", v.render());
        Ok(())
    }

    /// Pure in-memory mutation of a `[workspace.dependencies]` entry -- no
    /// disk I/O. See [`Self::write_version`]'s doc for why this no longer
    /// persists internally; callers must call [`Self::persist`] explicitly
    /// afterward.
                "{content}"
            );
        }
    }

    #[test]
    fn cargo_package_name_returns_none_when_absent() {
        let doc: toml_edit::DocumentMut = "[workspace]\nmembers = [\"crates/*\"]\n".parse().unwrap();
        assert_eq!(cargo_package_name(&doc), None);
    }

    #[test]
    fn workspace_root_manifest_path_normalizes_to_bare_cargo_toml() {
        let content = "[workspace]\nmembers = [\".\"]\n\n[package]\nname = \"root-pkg\"\nversion = \"1.0.0\"\nedition = \"2021\"\n";

        // Absolute root case: exercises WorkspaceCargoResolver::load's
        // is_absolute()==true branch (root_manifest_path.file_name()).
        let dir = tempdir().unwrap();
        let abs_root_cargo = dir.path().join("Cargo.toml");
        fs::write(&abs_root_cargo, content).unwrap();
        let abs_inheritance = WorkspaceCargoResolver::load(&abs_root_cargo)
            .unwrap()
            .inheritance()
            .unwrap();
        assert_eq!(abs_inheritance.root_manifest, PathBuf::from("Cargo.toml"));

        // Relative-input case: WorkspaceCargoResolver::load's is_absolute()==false
        // branch delegates directly to workspace_relative(root_manifest_path) with
        // no other transformation -- asserted directly here (rather than via a
        // cwd-swapping call to load()) since workspace_relative is the exact,
        // pure, cwd-independent function that branch calls.
        assert_eq!(
            callisto_model::workspace_relative(Path::new("Cargo.toml")).unwrap(),
            PathBuf::from("Cargo.toml")
        );

        // The other side of classify_manifest_writes' comparison: ManifestDecl::new's
        // own workspace_relative normalization of the workspace root's own canonical
        // manifest path.
        let decl = ManifestDecl::new(
            PathBuf::from(".").join("Cargo.toml"),
            ManifestRole::Canonical,
            ManifestFormat::CargoToml,
        )
        .unwrap();
        assert_eq!(decl.path, PathBuf::from("Cargo.toml"));
        assert_eq!(
            decl.path, abs_inheritance.root_manifest,
            "a root package's own canonical manifest path and WorkspaceCargoResolver's root_manifest must normalize identically for classify_manifest_writes' plain PathBuf equality to detect them as the same physical file"
        );
    }

    #[test]
    fn persist_is_exposed_as_a_manifest_trait_method() {
        let dir = tempdir().unwrap();
        let manifest_path = dir.path().join("Cargo.toml");
        let content = "[package]\nname = \"my-crate\"\nversion = \"0.1.0\"\n";
        fs::write(&manifest_path, content).unwrap();

