#[test]
fn root_package_release_commit_accepts_default_and_configured_changelog_paths() {
    let cases = [
        (
            "cargo/solo",
            "crates-io",
            "Cargo.toml",
            "[package]\nname = \"solo\"\nversion = \"0.1.0\"\nedition = \"2021\"\n",
            "src/lib.rs",
        ),
        (
            "npm/solo",
            "npm",
            "package.json",
            "{\"name\":\"solo\",\"version\":\"0.1.0\"}\n",
            "src/index.js",
        ),
        (
            "pypi/solo",
            "pypi",
            "pyproject.toml",
            "[project]\nname = \"solo\"\nversion = \"0.1.0\"\n",
            "src/solo/__init__.py",
        ),
    ];
    for (identity, registry, manifest, source, code) in cases {
        for custom_changelog in [false, true] {
            let dir = repo(&[(manifest, source), (code, "\n")]);
            let root = dir.path();
            init(root);
            let config = fs::read_to_string(root.join("callisto.toml")).unwrap();
            let changelog_config = if custom_changelog {
                "changelog = \"./notes/../RELEASES.md\"\n"
            } else {
                ""
            };
            callisto_model::atomic::atomic_write(
                &root.join("callisto.toml"),
                &format!(
                    "{config}\n[[package]]\nmatch = \"{identity}\"\npublish-to = [\"{registry}\"]\n\
                     {changelog_config}",
                ),
                &callisto_model::ApplyPermit::force_for_tests(),
            )
            .unwrap();
            commands::add::handle(
                AddArgs {
                    packages: vec!["solo:patch".to_owned()],
                    summary: Some("Fix the root package".to_owned()),
                },
                &global(root, false),
            )
            .unwrap();
            run_git(root, &["add", "."]);
            run_git(root, &["commit", "-q", "-m", "configure and request release"]);
            let decision_path = ".callisto/release-decision.json";
            commands::version::handle(
                VersionArgs {
                    refresh_lockfiles: false,
                    no_refresh_lockfiles: true,
                    strict: false,
                    allow_empty_changesets: false,
                    emit_decision: Some(decision_path.into()),
                },
                &global(root, false),
            )
            .unwrap();
            let changelog_path = if custom_changelog {
                "RELEASES.md"
            } else {
                "CHANGELOG.md"
            };
            assert!(root.join(changelog_path).exists());
            run_git(root, &["add", "."]);
            run_git(root, &["commit", "-q", "-m", "release root package"]);
            let head = std::process::Command::new("git")
                .args(["rev-parse", "HEAD"])
                .current_dir(root)
                .output()
                .unwrap();
            assert!(head.status.success());
            let commit = String::from_utf8(head.stdout).unwrap().trim().to_owned();
            run_git(root, &["checkout", "--detach", &commit]);
            let external = tempfile::tempdir().unwrap();
            let intent_path = external.path().join("intent.json");
            let out = std::process::Command::new(env!("CARGO_BIN_EXE_callisto"))
                .args([
                    "--cwd",
                    root.to_str().unwrap(),
                    "release",
                    "plan",
                    "--from-release-commit",
                    &commit,
                ])
                .args(["--decision", decision_path, "--out", intent_path.to_str().unwrap()])
                .output()
                .unwrap();
            assert!(
                out.status.success(),
                "{identity}, custom changelog {custom_changelog}: {}",
                String::from_utf8_lossy(&out.stderr),
            );
            let intent: callisto_model::ReleaseIntentV1 =
                serde_json::from_slice(&fs::read(intent_path).unwrap()).unwrap();
            assert_eq!(intent.decision.entries.len(), 1);
            assert_eq!(intent.decision.entries[0].package.to_string(), identity);
            assert_eq!(intent.decision.entries[0].target_version.render(), "0.1.1");
        }
    }
}
mod common;

use callisto_cli::cli::{AddArgs, GlobalArgs, OutputFormat, VersionArgs};
use callisto_cli::commands;

use common::setup_polyglot_git_repo;

mod inherited_versions {
    use std::fs;
    use std::path::Path;

    use callisto_fixtures::git::{init_repo, run_git, GitRunner};
    use callisto_graph::{commands::check_partial_run, locate::IgnoreWalkLocator, GraphError, Workspace};
    use callisto_model::{atomic::atomic_write, ApplyPermit};

    fn write(root: &Path, path: &str, content: &str) {
        let path = root.join(path);
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        atomic_write(&path, content, &ApplyPermit::force_for_tests()).unwrap();
    }

    fn root_manifest(version: &str) -> String {
        format!(
            "[workspace]\nmembers = [\"crates/member\"]\nresolver = \"2\"\n\n\
             [workspace.package]\nversion = \"{version}\"\n",
        )
    }

    fn fixture(pending: bool) -> tempfile::TempDir {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        init_repo(root);
        write(root, "Cargo.toml", &root_manifest("0.1.0"));
        write(
            root,
            "crates/member/Cargo.toml",
            "[package]\nname = \"member\"\nversion.workspace = true\nedition = \"2021\"\n",
        );
        write(root, "crates/member/src/lib.rs", "\n");
        callisto_fixtures::scaffold_callisto(root);
        if pending {
            write(
                root,
                ".changeset/pending.md",
                "---\nmember: patch\n---\n\nFix the member\n",
            );
        }
        run_git(root, &["add", "."]);
        run_git(root, &["commit", "-q", "-m", "initial workspace"]);
        dir
    }

    #[test]
    fn inherited_root_version_change_is_refused_with_pending_changesets_or_a_staged_authority() {
        for pending in [true, false] {
            let dir = fixture(pending);
            let root = dir.path();
            let member_before = fs::read(root.join("crates/member/Cargo.toml")).unwrap();
            write(root, "Cargo.toml", &root_manifest("0.1.1"));
            if !pending {
                run_git(root, &["add", "Cargo.toml"]);
            }
            let runner = GitRunner;
            let locator = IgnoreWalkLocator::new(root);
            let ws = Workspace::load(root.to_path_buf(), &locator, &runner).unwrap();
            let error = check_partial_run(&ws).unwrap_err();
            match error {
                GraphError::PartialVersionRun { path, disk, head } => {
                    assert_eq!(path, Path::new("Cargo.toml"));
                    assert_eq!(disk.render(), "0.1.1");
                    assert_eq!(head.render(), "0.1.0");
                }
                other => panic!("expected the partial-version diagnostic, got {other:?}"),
            }
            assert_eq!(fs::read(root.join("crates/member/Cargo.toml")).unwrap(), member_before);
        }
    }

    #[test]
    fn staged_workspace_metadata_without_an_effective_version_change_is_allowed() {
        let dir = fixture(false);
        let root = dir.path();
        write(
            root,
            "Cargo.toml",
            &format!("{}\n[workspace.metadata]\nchanged = true\n", root_manifest("0.1.0")),
        );
        run_git(root, &["add", "Cargo.toml"]);
        let runner = GitRunner;
        let locator = IgnoreWalkLocator::new(root);
        let ws = Workspace::load(root.to_path_buf(), &locator, &runner).unwrap();
        check_partial_run(&ws).expect("metadata alone does not signal an interrupted version run");
    }
}

/// Two `version` runs with nothing committed between them must refuse the second (E121), not stack a second bump.
#[test]
fn test_version_twice_without_commit_is_refused_as_partial_run() {
    let dir = setup_polyglot_git_repo();
    let root = dir.path();

    let global = GlobalArgs {
        format: OutputFormat::Json,
        cwd: root.to_path_buf(),
        dry_run: false,
    };

    callisto_fixtures::scaffold_callisto(&global.cwd);

    commands::add::handle(
        AddArgs {
            packages: vec!["core-crate:patch".to_string()],
            summary: Some("Fix the frobnication bug".to_string()),
        },
        &global,
    )
    .unwrap();

    commands::version::handle(
        VersionArgs {
            refresh_lockfiles: false,
            no_refresh_lockfiles: true,
            strict: false,
            allow_empty_changesets: false,
            emit_decision: None,
        },
        &global,
    )
    .expect("the first version run must succeed and stage its changes");

    let second = commands::version::handle(
        VersionArgs {
            refresh_lockfiles: false,
            no_refresh_lockfiles: true,
            strict: false,
            allow_empty_changesets: false,
            emit_decision: None,
        },
        &global,
    );

    assert!(
        second.is_err(),
        "a second `version` run with nothing committed since the first must be refused, not \
         silently apply a second bump on top of the first uncommitted one"
    );
    let message = second.unwrap_err().to_string();
    assert!(
        message.contains("this looks like a `version` run that wrote and staged its changes but never committed")
            || message.contains("E121"),
        "expected the partial-run (E121) refusal, got: {message}"
    );
}

