363	/// True when a canonical manifest differs between index and HEAD: `git add`ed by a prior `apply` but never committed.
364	fn any_canonical_manifest_staged_uncommitted<R: CommandRunner, D: DependencyResolver>(
365	    ws: &Workspace<'_, R, D>,
366	) -> Result<bool, GraphError> {
367	    let mut paths = std::collections::BTreeSet::new();
368	    for decl in ws.graph.packages().flat_map(|pkg| pkg.canonical_manifests()) {
369	        paths.insert(super::release_decision::normalized_git_path(&decl.path)?);
370	        if decl.ecosystem() == callisto_model::Ecosystem::Cargo {
371	            paths.insert("Cargo.toml".to_string());
372	        }
373	    }
374	    for path in paths {
375	        let output = ws
376	            .runner
377	            .run("git", &["diff", "--cached", "--quiet", "--", &path], &ws.root)
378	            .map_err(GraphError::Command)?;
379	        // `git diff --quiet` exits 1 on a difference, 0 on none; any other exit code is treated as no signal.
380	        if output.exit_code == Some(1) {
381	            return Ok(true);
382	        }
383	    }
384	    Ok(false)
385	}
