   394	/// Whether `<rev>:<path>` names an object; `--quiet` keeps a missing path from printing to stderr.
   395	fn head_object_exists<R: CommandRunner, D: DependencyResolver>(
   396	    ws: &Workspace<'_, R, D>,
   397	    spec: &str,
   398	) -> Result<bool, GraphError> {
   399	    let output = ws
   400	        .runner
   401	        .run("git", &["rev-parse", "--verify", "--quiet", spec], &ws.root)
   402	        .map_err(GraphError::Command)?;
   403	    Ok(output.success())
