   431	    ws: &Workspace<'_, R, D>,
   432	    head: &str,
   433	    path: &str,
   434	) -> Result<Option<String>, GraphError> {
   435	    let spec = format!("{head}:{path}");
   436	    if !head_object_exists(ws, &spec)? {
   437	        return Ok(None);
   438	    }
   439	    let output = ws
   440	        .runner
   441	        .run("git", &["show", &spec], &ws.root)
   442	        .map_err(GraphError::Command)?;
   443	    if !output.success() {
   444	        return Ok(None);
   445	    }
   446	    Ok(Some(output.stdout))
   447	}
